"use client";

import { Fragment, type CSSProperties } from "react";

/**
 * Accessible split text for the numeral-reveal animation. The parent
 * element carries the accessible name via `aria-label`; this span is
 * `aria-hidden` and purely visual — one <span> per glyph, each with a
 * `--i` index for the stagger. The entrance animation is opt-in: it only
 * runs under `.grid-js` when an ancestor carries `.is-on`, so without
 * JavaScript the numerals simply stand in place.
 *
 * Used for the oversized thin plate numbers and section titles. Where
 * RASTER's WidthMark splits to drive Archivo's width axis per glyph,
 * NumeralMark splits to fade-and-rise each glyph — a thinner, quieter
 * reveal that matches the atelier's register.
 *
 * Words are wrapped in nowrap spans separated by real spaces, so a long
 * number can break between words on a narrow sheet but never inside one.
 */
export default function NumeralMark({ text }: { text: string }) {
  const words = text.split(" ");
  const offsets: number[] = [];
  let acc = 0;
  for (const word of words) {
    offsets.push(acc);
    acc += word.length;
  }

  return (
    <span className="grid-nummark" aria-hidden="true">
      {words.map((word, w) => (
        <Fragment key={`${w}-${word}`}>
          {w > 0 ? " " : null}
          <span className="grid-nummark__word">
            {Array.from(word).map((ch, c) => (
              <span
                key={`${offsets[w] + c}-${ch}`}
                className="grid-nummark__ch"
                style={{ "--i": offsets[w] + c } as CSSProperties}
              >
                {ch}
              </span>
            ))}
          </span>
        </Fragment>
      ))}
    </span>
  );
}

"use client";

import {
  createContext,
  useCallback,
  useContext,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react";
import { flushSync } from "react-dom";
import { useFlip } from "../hooks/useFlip";
import { usePrefersReducedMotion } from "../hooks/usePrefersReducedMotion";
import type { Typology } from "./projects";

export type Filter = Typology | "all";

type PlateContextValue = {
  filter: Filter;
  setFilter: (next: Filter) => void;
};

const PlateContext = createContext<PlateContextValue>({
  filter: "all",
  setFilter: () => undefined,
});

export function usePlate(): PlateContextValue {
  return useContext(PlateContext);
}

const COLS = 12;

/**
 * Owns the typology filter. The default — and the static, no-JS board —
 * is "all works": every plate shown. `setFilter` re-snaps every
 * `[data-flip]` plate via FLIP (`flushSync` makes the layout change
 * synchronous between the two measurements); under reduced motion the
 * repack is instant.
 *
 * The provider also renders the exposed construction: a fixed column
 * overlay of faint ink hairlines at the content's exact frame. Where
 * RASTER cross-fades two grid layers (6 and 12) to prove its column count
 * changed, GRID keeps one 12-col overlay always on — the grid is the
 * *instrument* here, not the *subject*, so it stays put while the work
 * moves across it.
 */
export default function PlateScope({ children }: { children: ReactNode }) {
  const [filter, setFilterState] = useState<Filter>("all");
  const reduced = usePrefersReducedMotion();
  const scopeRef = useRef<HTMLDivElement | null>(null);
  const flip = useFlip(scopeRef);

  const setFilter = useCallback(
    (next: Filter) => {
      if (next === filter) return;
      if (reduced) {
        setFilterState(next);
        return;
      }
      flip(() => {
        flushSync(() => setFilterState(next));
      });
    },
    [filter, reduced, flip],
  );

  const value = useMemo(() => ({ filter, setFilter }), [filter, setFilter]);

  return (
    <PlateContext.Provider value={value}>
      <div ref={scopeRef} className="grid-scope" data-filter={filter}>
        <div className="grid-overlay" aria-hidden="true">
          <div className="grid-overlay__layer">
            {Array.from({ length: COLS }, (_, i) => (
              <span key={i} />
            ))}
          </div>
        </div>
        {children}
      </div>
    </PlateContext.Provider>
  );
}

